// One incident shape for both ways in (design part 1):
//  - Error Trigger: n8n hands over a failed execution of any workflow whose settings.errorWorkflow is this one:
//    {execution: {id, url, lastNodeExecuted, mode, error: {message, name}}, workflow: {id, name}}
//    -> source error_workflow, kind = the error class, ref = the execution id (the number the user's error line shows).
//  - Incident webhook (POST /webhook/rag-incident, bearer token): the pipe, backups, evals, the watchdog and the
//    in-workflow error branches send {source, kind, message, ref?, workflow?, workflow_id?, node?, execution_id?, data?}.
//    source eval + kind run carries the run in data (-> eval_run); kind ok is recorded, never alerted.
// Text hygiene: an incident never carries the question. Azure and Postgres errors can quote the request body, so the
// message is cut at the first chatInput, messages or content (any letter case), then capped at 300 characters. The
// workflow and node names get the same cut: they reach the alert header. Request headers (the token) and error
// stacks/descriptions are never read; data is capped at 4,000 characters.
const CUT_AT = ['chatInput', 'messages', 'content'];
const CUT_RE = new RegExp(CUT_AT.join('|'), 'i');   // case-insensitive match: indices stay those of the original text
const cut = (v) => {
  if (v === undefined || v === null || v === '') return null;
  const t = String(v), i = t.search(CUT_RE);
  return (i >= 0 ? t.slice(0, i) : t).replace(/\s+/g, ' ').replace(/[\s{\[("',:=]+$/, '').trim();
};
const scrub = (v) => { const t = cut(v); return t === null ? null : (t.slice(0, 300) || '(error text withheld: it quoted the request)'); };
const scrubName = (v) => { const t = cut(v); return t === null ? null : (t.slice(0, 120) || '(withheld)'); };
const DATA_MAX = 4000;
const capData = (d) => {
  if (d === null) return null;
  const s = JSON.stringify(d);
  if (s.length <= DATA_MAX) return d;
  const out = { truncated: true, chars: s.length, ...(d.workflow_id ? { workflow_id: String(d.workflow_id).slice(0, 40) } : {}), preview: '' };
  for (let n = DATA_MAX; n > 0; n = Math.floor(n * 0.8)) { out.preview = s.slice(0, n); if (JSON.stringify(out).length <= DATA_MAX) return out; }
  delete out.preview;
  return out;
};
const clip = (v, n) => { const t = v === undefined || v === null ? '' : String(v).replace(/\s+/g, ' ').trim().slice(0, n); return t || null; };
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

const normalize = (x) => {
  if (isObj(x.execution) || isObj(x.trigger)) {
    const e = (isObj(x.execution) ? x.execution : x.trigger).error ?? {};
    const cls = e.name || (String(e.stack ?? '').match(/^\s*([A-Za-z]*Error)\b/) ?? [])[1] || 'error';
    const id = clip(x.execution?.id, 40);
    const wid = clip(x.workflow?.id, 40);
    return { source: 'error_workflow', kind: clip(cls, 60), workflow: scrubName(x.workflow?.name), workflow_id: wid,
             node: scrubName(x.execution?.lastNodeExecuted ?? e.node?.name), message: scrub(e.message) ?? '(no error message)',
             execution_id: id, ref: id,
             data: capData({ workflow_id: wid, mode: clip(x.execution?.mode ?? x.trigger?.mode, 20), retry_of: clip(x.execution?.retryOf, 40) }) };
  }
  const b = isObj(x.body) ? x.body : {};
  const wid = clip(b.workflow_id ?? (isObj(b.data) ? b.data.workflow_id : null), 40);
  const data = isObj(b.data) ? { ...b.data } : (b.data === undefined || b.data === null ? {} : { value: b.data });
  if (wid) data.workflow_id = wid;
  const exec = clip(b.execution_id, 40);
  return { source: clip(b.source, 40) ?? 'unknown', kind: clip(b.kind, 60) ?? 'unknown', workflow: scrubName(b.workflow),
           workflow_id: wid, node: scrubName(b.node), message: scrub(b.message), execution_id: exec, ref: clip(b.ref, 40) ?? exec,
           data: capData(Object.keys(data).length ? data : null) };
};
return $input.all().map((item) => ({ json: normalize(item.json) }));

// The Telegram alert (design part 1): what failed and when, the scrubbed message, ref + editor link, "+N more", and
// the runbook section. Never question text; every value is HTML-escaped (Telegram parse_mode HTML).
const EDITOR_URL = "http://localhost:5680/";
const CHAT_AGENTS = ["zWAl3yeuiJPsldXV", "ragChatVision001", "ragChatVisionT01"];
const INGESTION = "GwkCOkOcb9EAOX9e";
const SECTION = {
  chat: 'Runbook: Chat agent errors', ingestion: 'Runbook: Ingestion errors', other: 'Runbook: Workflow errors',
  watch: 'Runbook: Service down', backup: 'Runbook: Backup failed', eval: 'Runbook: Eval drop',
};
const BY_SOURCE = { chat_agent: SECTION.chat, look_at_pages: SECTION.chat, pipe: SECTION.chat,
                    watch: SECTION.watch, backup: SECTION.backup, eval: SECTION.eval };
const LABEL = { pipe: 'Open WebUI pipe', backup: 'Backup', eval: 'Evals', watch: 'Watch', chat_agent: 'Chat agent', look_at_pages: 'Look at pages' };
const runbook = (r) => r.source === 'error_workflow'
  ? (CHAT_AGENTS.includes(r.workflow_id) ? SECTION.chat : r.workflow_id === INGESTION ? SECTION.ingestion : SECTION.other)
  : (BY_SOURCE[r.source] ?? SECTION.other);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const stamp = (at) => {
  let d = new Date(at ?? Date.now());
  if (isNaN(d)) d = new Date();
  const p = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Los_Angeles', weekday: 'short', month: 'short',
    day: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(d).map((x) => [x.type, x.value]));
  return `${p.weekday} ${p.month} ${p.day} ${p.hour}:${p.minute} PT`;
};
const alert = (r) => {
  const label = r.workflow ? String(r.workflow).replace(/^RAG\s*[–-]\s*/, '') : (LABEL[r.source] ?? r.source);
  const head = ['🔴 <b>RAG incident</b>', esc(label), r.node ? `node "${esc(r.node)}"` : null,
                r.source === 'error_workflow' ? null : esc(r.kind), stamp(r.at)].filter(Boolean).join(' · ');
  const link = r.execution_id && r.workflow_id
    ? `${EDITOR_URL}workflow/${encodeURIComponent(r.workflow_id)}/executions/${encodeURIComponent(r.execution_id)}` : null;
  const ref = [r.ref ? `ref ${esc(r.ref)}` : null, link ? esc(link) : null].filter(Boolean).join(' · ');
  const more = Number(r.suppressed) > 0 ? `(+${Number(r.suppressed)} more in the last 30 min)` : null;
  const lines = [head, esc(r.message || '(no message)'), [ref, more].filter(Boolean).join('  '), runbook(r)];
  return { id: r.id, text: lines.filter(Boolean).join('\n') };
};
return $input.all().map((item) => ({ json: alert(item.json) }));
